    "limitations": "Licensing evidence is derived entirely from published disclaimers on the company's contact and schedule pages; state licensing database confirmation was not performed."
  },
  "existingSoftware": [
    {
      "product": "ServiceTitan",
      "purpose": "Field-service management software and marketing assets",
