    {
      "product": "Formidable Forms",
      "purpose": "WordPress website form builder used for service bookings, contact messages, and job applications",
      "evidence": {
        "statement": "Form handling scripts on contact, schedule, and career pages are loaded from the Formidable plugin directory.",
        "label": "inference",
        "sourceUrl": "https://plumbingsolutionsofidaho.com/contact-us/",
        "quote": null
      }
    },
    {
      "product": "ClickCease",
      "purpose": "Pay-per-click ad fraud detection and protection",
      "evidence": {
        "statement": "Pages across the website communicate with ClickCease tracking hosts.",
        "label": "inference",
        "sourceUrl": "https://plumbingsolutionsofidaho.com/",
        "quote": null
      }
    },
    {
      "product": "Choozle",
      "purpose": "Digital programmatic advertising and audience tracking",
      "evidence": {
        "statement": "Website pages load the Choozle advertising bootstrap script.",
        "label": "inference",
        "sourceUrl": "https://plumbingsolutionsofidaho.com/",
        "quote": null
      }
    },
    {
