      "purpose": "Local project check-ins and customer review generation",
      "evidence": {
        "statement": "The company's website references the RealWork Labs application host.",
        "label": "inference",
        "sourceUrl": "https://plumbingsolutionsofidaho.com/about/recent-projects/",
