      "purpose": "Applicant tracking and recruitment management",
      "evidence": {
        "statement": "The careers page links to an ApplicantPro portal for candidate recruitment.",
        "label": "inference",
        "sourceUrl": "https://plumbingsolutionsofidaho.com/about/careers/",
        "quote": null
      }
    },
    {
      "product": "Service Finance Company / GreenSky",
      "purpose": "Consumer financing portal integration for residential plumbing projects",
      "evidence": {
        "statement": "The financing page includes direct forms and links to Service Finance Company and GreenSky platforms.",
        "label": "inference",
        "sourceUrl": "https://plumbingsolutionsofidaho.com/about/financing/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The booking page utilizes a Formidable WordPress form that submits directly to the local WordPress page rather than an embedded real-time field service booking engine.",
      "label": "inference",
      "sourceUrl": "https://plumbingsolutionsofidaho.com/schedule-service/",
      "quote": null
    },
    {
      "statement": "The online booking form lists options for 'Air Conditioning' and 'Heating' alongside plumbing services, despite the company operating primarily as a plumbing specialist.",
      "label": "fact",
      "sourceUrl": "https://plumbingsolutionsofidaho.com/schedule-service/",
      "quote": "Service Needed * Air Conditioning Heating Plumbing Sewers Drains"
    },
    {
      "statement": "The company invests actively in paid digital acquisition across Google, Bing, Facebook, and display networks as indicated by remarketing and ClickCease integrations.",
      "label": "inference",
      "sourceUrl": "https://plumbingsolutionsofidaho.com/privacy-policy/",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Potential lead intake latency or manual data re-entry between WordPress Formidable forms and the central field-service management platform (ServiceTitan).",
      "label": "hypothesis",
      "basis": "The website uses Formidable Forms submitting to WordPress rather than an integrated ServiceTitan web booking widget, meaning form submissions likely route via email to dispatch."
    },
    {
      "problem": "Mismatched service category selections on the primary scheduling form ('Air Conditioning' and 'Heating' on a plumbing site) causing misrouted or unqualified triage.",
      "label": "inference",
      "basis": "https://plumbingsolutionsofidaho.com/schedule-service/"
    },
    {
      "problem": "Incomplete attribution or reporting latency across multi-channel paid ad sources (Google Ads, Bing Ads, Facebook, Choozle) and booked revenue in ServiceTitan.",
      "label": "hypothesis",
      "basis": "Active presence of multiple ad platforms and ClickCease click protection suggests significant marketing spend, where cross-platform cost-per-booked-job reporting often requires manual aggregation."
    }
  ],
  "existingSolutions": [
    {
      "solution": "ServiceTitan Web Booking Widget",
      "addresses": "Directly injects customer booking requests into ServiceTitan scheduling dispatch with live availability and automatic customer profile creation.",
      "alreadyOwned": true
    },
    {
      "solution": "Formidable Forms Webhooks / Zapier Add-on",
      "addresses": "Automatically triggers an API payload from WordPress form submissions to external CRMs or ServiceTitan Booking API.",
      "alreadyOwned": false
    },
    {
      "solution": "ServiceTitan Marketing Pro / ROI Analytics",
      "addresses": "Tracks revenue attribution by campaign and integrates ad spend reporting with dispatch outcomes.",
      "alreadyOwned": false
    }
  ],
  "forgexSolutions": [
    {
      "name": "Revenue Leak Check",
      "kind": "catalog",
      "description": "A one-week operational diagnostic auditing web form response speeds, off-hours dispatch handling, call attribution, and missed inquiries against booked jobs.",
      "problem": "Unverified lead drop-off between paid advertising clicks, website form submissions, and actual dispatch board booking.",
      "whyNotExistingSoftware": "ServiceTitan and Google Analytics track activity within their own silos but do not benchmark end-to-end response lag or measure off-hours leakage without independent auditing."
    },
    {
      "name": "Lead-to-job pipeline",
      "kind": "catalog",
      "description": "Integration bridge connecting website Formidable booking forms directly to ServiceTitan's Booking API within two minutes, with automated customer confirmation SMS.",
      "problem": "Forms currently route to WordPress/dispatch email, risking manual transcription delay during peak call periods or overnight.",
      "whyNotExistingSoftware": "While ServiceTitan provides an off-the-shelf booking widget, contractors often prefer custom on-brand forms that require lightweight middleware to post cleanly into ServiceTitan."
    },
    {
      "name": "Owner's Monday numbers",
      "kind": "catalog",
      "description": "Single-page weekly dashboard compiling booked plumbing revenue, average ticket, ad spend, and cost per booked call across ServiceTitan, ad networks, and QuickBooks.",
      "problem": "Disparate reporting across Choozle, ClickCease, Google Ads, and ServiceTitan complicates weekly commercial visibility.",
      "whyNotExistingSoftware": "Standard platform dashboards do not unify third-party ad network spend, accounting data, and field job completion in one simple Monday executive report."
    }
  ],
  "feasibility": {
    "rating": "high",
    "explanation": "The company's digital stack uses standard WordPress architecture with Formidable Forms alongside ServiceTitan infrastructure, both of which support webhooks and REST APIs for automated data synchronization."
  },
  "aiDelivery": {
    "rating": "partly",
    "explanation": "AI models can handle conversational triage, inquiry categorization, and draft dispatch replies, but core lead pipeline synchronization and dashboard aggregation rely on deterministic API connectors."
  },
  "humanReview": [
    "Dispatchers must review and confirm technician job assignments before finalizing appointments on the calendar.",
    "Emergency service inquiries submitted after-hours require immediate dispatcher telephone verification.",
    "Weekly executive metrics must be reconciled against certified bank and accounting statements."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Automated form routing must not bypass on-call emergency dispatch protocols for urgent situations like flooding or ruptured water lines."
    },
    {
      "type": "compliance",
      "description": "SMS notifications to customers submitting booking requests must strictly honor TCPA consent checkboxes already implemented on the site forms."
    },
    {
      "type": "security",
      "description": "API keys connecting WordPress form endpoints to ServiceTitan or reporting databases must be secured against unauthorized access."
    }
  ],
  "commercial": {
    "supportable": true,
    "value": "$7,200 to $12,000 annually (illustrative)",
    "implementationCost": "$1,800 setup plus $149/month for Lead-to-job pipeline, or $500 for Revenue Leak Check",
    "assumptions": [
      "Plumbing Solutions of Idaho advertises standard drain cleaning jobs costing between $100 and $300 (average midpoint $200).",
      "If lead intake delays or missed follow-ups cause 3 to 5 standard drain cleaning jobs ($200 each) to slip through per month, illustrative lost gross revenue is $600 to $1,000 monthly ($7,200 to $12,000 annually).",
      "Value will be higher if larger repairs or installations (such as water heaters or repiping) are delayed or lost."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / President",
      "General Manager",
      "Operations Manager / Dispatch Manager"
    ],
    "people": [],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://plumbingsolutionsofidaho.com/contact-us/"
      },
      {
