      {
        "kind": "web form",
        "value": "https://plumbingsolutionsofidaho.com/schedule-service/",
        "sourceUrl": "https://plumbingsolutionsofidaho.com/schedule-service/"
      },
      {
        "kind": "web form",
        "value": "https://plumbingsolutionsofidaho.com/contact-us/",
        "sourceUrl": "https://plumbingsolutionsofidaho.com/contact-us/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "When a customer submits a service request on your schedule page, how does that inquiry currently enter ServiceTitan—via direct API, email alert to dispatch, or manual entry?",
      "How do your on-call dispatchers handle after-hours or weekend web form submissions for emergency plumbing calls?",
      "How do you currently track marketing spend efficiency across Google Ads, Choozle, and other channels down to completed jobs in ServiceTitan?"
    ],
    "outreachSubject": "Service scheduling workflow / Plumbing Solutions of Idaho",
    "outreachBody": "Hi [Owner / General Manager Name],\n\nMy name is [Founder Name] with ForgeX. We work with established plumbing and home-service trade contractors to streamline lead intake and field-service integration.\n\nWhile reviewing your website, I noticed your online service scheduling page uses a custom WordPress form that appears to route to your dispatch email, even though your site references ServiceTitan assets. In many plumbing operations, web submissions can take valuable minutes to get transcribed into ServiceTitan, especially during morning dispatch rushes or overnight emergency calls.\n\nWe don't sell generic software and don't make promises without understanding your specific workflow. If you or your dispatch team ever find that web inquiries or after-hours requests create unnecessary transcription work, I'd welcome the chance to share how similar plumbing contractors bridge that pipeline automatically.\n\nIf you prefer not to hear from us, simply reply with 'opt out' or 'remove' and I will respect your preference immediately.\n\nBest regards,\n\n[Founder Name]\nFounder, ForgeX\n[Founder Street Address, City, State, ZIP]\n[Founder Phone Number] | [Founder Email]"
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://plumbingsolutionsofidaho.com/",
        "usedFor": "Company name, primary phone, email, 24/7 service statement, tech stack scripts and hosts"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/about/",
        "usedFor": "Company founding year, location, review statistics, service overview, secondary phone"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/about/meet-the-team/",
        "usedFor": "Personnel verification (confirmed absence of named executive leadership)"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/contact-us/",
        "usedFor": "Physical address, plumbing license number (PLB-C-12709), Formidable contact form structure"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/schedule-service/",
        "usedFor": "Online booking form structure, service categories (including AC/Heating), SMS opt-in terms"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/about/careers/",
        "usedFor": "Benefits packages, applicant tracking platform reference (ApplicantPro)"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/about/community/",
        "usedFor": "BBB Torch Award for Ethics, Chamber of Commerce Business of the Year, community initiatives"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/about/financing/",
        "usedFor": "Financing integrations (Service Finance Company, GreenSky)"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/about/coupons/",
        "usedFor": "Stated promotional pricing ($99 water heater flush, $50 off plumbing)"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/drains-sewers/drain-cleaning/",
        "usedFor": "Stated pricing range ($100 to $300 for standard drain cleaning jobs)"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/water-heaters/water-heater-repair/",
        "usedFor": "Water heater service offerings and promotional discounts"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/terms-and-conditions/",
        "usedFor": "SMS service terms, dispatch email verification, legal provisions"
      },
      {
        "url": "https://plumbingsolutionsofidaho.com/privacy-policy/",
        "usedFor": "Advertising platforms verification (Google Ads, Bing Ads, Facebook remarketing)"
      }
    ],
    "limitations": [
      "No individual owner, executive, or manager names are listed on the public website.",
      "Internal dispatch workflows and whether Formidable Forms connects to ServiceTitan via backend webhooks cannot be definitively confirmed from public frontend inspection.",
      "State licensing registry records were not independently inspected beyond the contractor license number published on site."
    ]
  },
  "qualification": {
    "category": "pursue later",
    "rationale": "Plumbing Solutions of Idaho fits ForgeX's target profile: an established owner-led plumbing contractor in Meridian, ID with ~10 to 75 personnel, active paid advertising (Google Ads, Bing Ads, Choozle, ClickCease), and field-service software (ServiceTitan). Observable operational surfaces exist—such as web booking through WordPress Formidable Forms rather than ServiceTitan's live booking widget, and mismatched HVAC options on their booking form. However, because public website analysis cannot verify whether their dispatch team experiences delays or already utilizes custom webhook automation into ServiceTitan, the operational problems remain hypotheses. The account should be pursued later via founder discovery questions."
  }
}
